"""Step 5: emit the runtime phrase list (display strings only) for the package.

Editorial annotations (jokes, categories, provenance, source spellings) stay in
research/editorial/curated.json and are NOT bundled.

Usage: python3 -I 05_build_runtime_data.py <curated.json> <out phrases.ts>
"""
import json
import sys


def main(src: str, out: str) -> None:
    names = sorted({c["name"] for c in json.load(open(src))}, key=lambda s: (s.lower(), s))
    lines = [
        "// GENERATED by research/scripts/05_build_runtime_data.py from",
        "// research/editorial/curated.json. Do not edit by hand.",
        "// Sorted alphabetically; any change here changes seeded output, so bump",
        "// DICTIONARY_VERSION in src/version.ts.",
        "export const CURATED: readonly string[] = [",
    ]
    lines += [f"  {json.dumps(n)}," for n in names]
    lines.append("];")
    open(out, "w").write("\n".join(lines) + "\n")
    print(f"wrote {len(names)} phrases to {out}")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
